import React, { useState } from "react";
 const Registration = () => {
    const [user , setUser] = useState({email :"" , password :"" , username :""})
    const signUp =( ) =>{}
    const handleUserChange =( ) =>{}
    return (
        <div>
            <div>
                <h2> Sign up :</h2>
                <form>
          <div className="mb-3">
            
            <input type="text" name="username"  value={user.username} onChange={handleUserChange} placeholder="Enter full name" />
          </div>
          <div className="mb-3">
           
            <input type="email" name="email" value={user.email} onChange={handleUserChange}  placeholder="Enter your email" />
          </div>

           <div className="mb-3">
          <input type="password" name="password" value={user.password} onChange={handleUserChange}  placeholder="Enter Password" />
         </div>
          <button type="submit" className="btn btn-primary" onClick={signUp}>Sign Up</button>
          
        </form>
            </div>
        </div>
    )
 }
 export default Registration;
